WITH inner_cte AS ( SELECT so.OFFER_DEPT_NAME, COUNT(DISTINCT so.SUBJECT_KEY) AS num_subjects_offered FROM SUBJECT_OFFERED so JOIN TIP_SUBJECT_OFFERED tip ON so.TERM_CODE = tip.TERM_CODE WHERE so.OFFER_DEPT_NAME = 'Harvard Cross-Enrollment Prog' AND so.OFFER_DEPT_NAME <> 'Chemistry' GROUP BY so.OFFER_DEPT_NAME ) SELECT ic.OFFER_DEPT_NAME, ic.num_subjects_offered, SUM(so.NUM_ENROLLED_STUDENTS) AS total_enrollment FROM inner_cte ic JOIN SUBJECT_OFFERED so ON ic.OFFER_DEPT_NAME = so.OFFER_DEPT_NAME GROUP BY ic.OFFER_DEPT_NAME, ic.num_subjects_offered ORDER BY ic.num_subjects_offered DESC LIMIT 10;